import unittest

from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import timesheet_lines

def make_shift(worker: str, day: str, span: str) -> Shift:
    return Shift(worker, day, parse_span(span))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_totals(self):
        shifts = [
            make_shift("Odell", "mon", "09:00-11:00"),
            make_shift("Odell", "tue", "09:00-11:30"),
            make_shift("Quill", "fri", "08:00-12:00"),
            make_shift("Brisa", "mon", "09:00-17:00"),
            make_shift("Brisa", "wed", "09:00-10:20"),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 9.3 hours",
                "Odell: 2 shifts, 4.5 hours",
                "Quill: 1 shifts, 4.0 hours"
            ]
        )

    def test_equal_minutes_sorted_by_name(self):
        shifts = [
            make_shift("Zed", "mon", "09:00-10:00"),
            make_shift("Ada", "mon", "10:00-11:00"),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ada: 1 shifts, 1.0 hours",
                "Zed: 1 shifts, 1.0 hours"
            ]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        shifts = [make_shift("  ", "mon", "09:00-10:00")]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
